# make list of sites
sites <- unique(gsub("_.*", "", colnames(hapfire)))
  # NOTE: suspected — this silently DROPS the 30th site (positional index, not
  # a site id); confirm that is intended.
sites <- sites[c(-30)]

output_ne <- paste("/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/", today, "/waples_1989_ne_esitmates.txt", sep = "")

check_file_exists(output_ne)

for(site in as.numeric(unique(sites))){
  local({
  print(paste("Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  for(exprep in 1:12){
    print(paste("Rep:", exprep))
    hap_rep <- hap_site %>% 
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect()
    
    # sort names to be in order of generation
    hap_rep <- hap_rep %>% relocate(all_of(sort(colnames(hap_rep))))
    
    if(ncol(hap_rep) == 0){
      print("No observations. Skipping replicate...")
      next
    }
    
    # get last column == last generation
    pt <- hap_rep %>% pull(ncol(hap_rep))
    
    # sample sizes
        # NOTE: suspected — grab_sample_sizes() takes a 5th argument (n_col) and this
        # call omits it, so the returned table has ONE column (site_gen_plot) plus a
        # warning, rep_n$n is NULL and the Ne estimate collapses to numeric(0).
        # Also: `sample_sizes` is the hapFIRE table, built in chunk #6, whose n has
        # already been doubled to CHROMOSOME counts (line 'sample_sizes$n <- 2*n'),
        # while S0 = 1000 below is passed as DIPLOID individuals — waples_ne()'s 1/S0
        # and 1/St terms are therefore in different units.
    rep_n <- grab_sample_sizes(sample_sizes, site_gen_plot, colnames(hap_rep), 1000)
    
    # check for minimum separation to avoid negative Ne estimates
        # NOTE: suspected fragile regex — "_._" matches any single character between
        # underscores, so it only parses generation labels while they are 1 digit.
    rep_time <- as.numeric(gsub("_", "", str_extract(colnames(hap_rep), "_._")))
    rep_time <- rep_time[length(rep_time)]
    
    # if(rep_time < 2){
    #   print("Too close to t too close to 0. Skipping replicate...")
    #   next
    # }
    
    # calculate Ne
        # NOTE: suspected FATAL — `gen0` is the kmate seedmix here (chunk #38), whose
        # columns are chrom, pos, class, X0_0_0; gen0$X3 is NULL, so fc()'s
        # stopifnot(length(p0) == length(pt)) aborts the job on the first replicate.
        # The kmate seedmix frequencies live in gen0$X0_0_0.
    ne_estimate <- waples_ne(1.8, 20, gen0$X3, pt, 1000, rep_n$n[nrow(rep_n)], rep_time)
    
    ne_result <- data.frame(
      site = site,
      rep = exprep,
            # NOTE: suspected — same NULL gen0$X3 issue as above.
      fc = fc(gen0$X3, pt),
      ne_low = ne_estimate[1],
      ne_high = ne_estimate[2],
      t = rep_time
    )
    
    append_table(ne_result, output_ne)
  }
  })
}
